\begin{abstract}
 Given a polygon $H$ in the plane, the art gallery problem calls for fining the smallest set of points in  $H$ from which every other point in $H$ is seen. We give a deterministic algorithm that, given any polygon $H$ with $h$ holes, $n$ rational veritces of maximum bit-length $L$, and a parameter $\delta \in(0,1)$, is guaranteed to find a set of points in $H$ of size $O\big(\OPT\cdot\log(h+2)\cdot\log (\OPT\cdot\log(h+2)))$ that sees at least a  $(1-\delta)$-fraction of the area of the polygon. The running time of the algorithm is polynomial in $n$, $L$ and $\log(\frac{1}{\delta})$ and quasi-polynomial in $h$, where $\OPT$ is the size of an optimum solution.
\end{abstract}

\label{sec:algorithm}
The algorithm, shown as Algorithm \ref{alg} below, proceeds in iterations $t=0,1,2,\ldots$. At any iteration $t$, the algorithm maintains a (possibly multi-) set of candidate guard locations $P_t\subset H$ (initially $P_0=\emptyset$), which is extended by exactly one point in each iteration. 
Let us define the {\it active} polygon $H_t\subseteq H$ as
\begin{align}
H_t := \{q \in H~:~|P_t\cap \Vis(q)| < T\}.\label{Ht}
\end{align}


In the algorithm , we assume that there is an {\it oracle} \MO$(H,H',w,\nu)$ that, given a polygon $H$, a set of points $H'\subseteq H$, a weight function $w:H\to\RR_+$, and an accuracy parameter $\nu\in(0,1)$, returns a point $p\in H$ such that
$$
w(\Vis_{H'}(p))\geq (1-\nu)\max_{q\in H}w(\Vis_{H'}(q)).
$$
(In that sense, the algorithm can be considered as an iterative variant of a weighted greedy algorithm.)
We will show in Section~\raf{sec:det} how such an oracle can be implemented in deterministic polynomial time.


\begin{algorithm}[H]
	\label{alg}
	\SetAlgoLined
	\KwData{A polygon $H$ and approximation accuracies $\eps,\delta,\nu\in(0,1)$}
	\KwResult{A $(\frac{1+2\eps}{1-\nu},1-\delta)$-approximate solution $P\subseteq H$}

	$t\gets 0$; $P_0\gets\emptyset$; $T\gets\frac1{\eps^2}\ln\frac{1}{\delta}$; $H_0\gets H$\\
			$w_0(q)\gets 1$ for all $q\in H_0$\\
	\While{$\area(H_t)\ge\delta\cdot\area(H)$}{
		$p_{t+1}\gets\MO(H,H_t,w_t,\nu)$ \label{s-oracle}\\
		$P_{t+1}\gets P_{t}\cup\{p_{t+1}\}$\\
		\For{$q\in H$	}{
			\tcp{Implicitly}	    
			$w_{t+1}(q) \gets \left\{\begin{array}{ll}(1-\eps)w_t(q)&\text{ if }q\in \Vis(p_{t+1})\cap H\\
	    w_t(q)&\text{ otherwise }\end{array}\right.$ \label{s-wt-red}}
		$t \gets t+1$\\
	}
    $\widehat P\gets P_t$; $\widehat \mu(p)\gets\frac1T$ for all $p\in\widehat P$; $\epsilon\gets\frac1{\widehat\mu(\widehat P)}$\\
	\Return an $\epsilon$-net of size $s_{\cF_H}(\frac1\epsilon)$ from the set $P_t$
	\caption{The MWU (weighted greedy) algorithm.}
\end{algorithm}

Given the set of points $P_t$ in iteration $t$, we get a partition of $H$ into a set of regions $\cR_t$ such that for any $R\in \cR_t$ all points in $R$ see the the same subset of points from $P_t$, that is, for all $p,q\in R$, $\Vis_{P_t}(p)=\Vis_{P_t}(q)$; see Fig.~\ref{fig34} for an illustration. Such a partition can be found in polynomial time in $n$, $h$ and $|P_t|=t$.  Indeed, it can be easily seen that the set of (visibility polygons of) the points in $P_t$, together with the set of vertices $V(H)$ of the polygon $H$, induces an arrangement of line segments (in $\RR^2$) of total complexity (say, number of faces) $r_t:=O(n(h+1)t^2)$; see., e.g.,~\cite{EH06}.  Thus, we can construct the set of (disjoint convex) cells of this arrangement, call it $\cC_t(H)$, in $O(n(h+1)t^2\log(n(h+1)t))$ time\footnote{For simplicity of presentation, we do not attempt here to optimize the running time, for instance, by maintaining a data structure for computing $\cells_t(H)$, which can be efficiently updated when a new point is added to $P_t$.}, and label each cell $R\in\cC_t(H)$ of the arrangement by the set of points $P_t(R)$ from $P_t$ it sees (e.g., using a sweep line algorithm), that is, $P_t(R)=\{p\in P_t~:~p\sees q\text{ for all }q\in R\}$.

\label{sec:analysis}
We first make a few easy observations that will be useful in the analysis of the algorithm.

\begin{observation}\label{ob1}
	For all $t\ge 0$, $R\in\cells_t(H)$, it holds that $w_t(R)=(1-\eps)^{|P_t(R)|}w_0(R)$. Consequently, $w_t(H_t)>(1-\eps)^Tw_0(H_t)$.
\end{observation}
\begin{proof}
	The first claim can be easily seen by induction on $t\ge0$ with the base case being trivial. Assume the claim holds for some $t>0$, and consider $R\in\cells_{t+1}(H)$. Note that $\cells_{t+1}(H)$ is a refinement of  $\cells_t(H)$ as some of the sets in $\cells_t(H)$ may be partially seen by the new point $p_{t+1}$. If $R\not\subseteq \Vis(p_{t+1})$, then $w_{t+1}(R)=w_t(R)=(1-\eps)^{|P_t(R)|}w_0(R)=(1-\eps)^{|P_{t+1}(R)|}w_0(R)$; otherwise, line~\ref{s-wt-red} of the algorithm implies that $w_{t+1}(R)=(1-\eps)w_t(R)=(1-\eps)^{|P_{t}(R)|+1}w_0(R)=(1-\eps)^{|P_{t+1}(R)|}w_0(R)$.

	The second claim is immediate from the first claim as def.~\raf{Ht} of $H_t$ implies
	\begin{align*}
	w_t(H_t)&=w_t\left(\bigcup_{R\in\cells_t(H):~|P_t(R)|<T}R\right)= \sum_{R\in \cells_t(H):~|P_t(R)|<T}w_t(R)\\&=\sum_{R\in\cells_t(H):~|P_t(R)|<T}(1-\eps)^{|P_t(R)|}w_0(R)\\&>(1-\eps)^T\sum_{R\in\cells_t(H) :~|P_t(R)|<T}w_0(R)=(1-\eps)^Tw_0(H_t).
	\end{align*}
\end{proof}









The analysis of the algorithm follows from the following three lemmas. The proofs are essentially the same as in~\cite{E23} (with some simplifications as~\cite{E23} compares the algorithm's output to an optimum {\it fractional} solution) and are included for completeness.
