\begin{lemma} \label{l1} For all $t=0,1,\ldots$, it holds that
	\begin{align}
	w_t(H_t) \leq w_0(H) \exp\left( -\frac{\eps(1-\nu)t}{\OPT}\right).
	\end{align}
\end{lemma}
\begin{proof}
	We first prove that
		\begin{align}\label{e1-1}
	w_{t+1}(H_{t+1})<\exp\left(-\frac{\eps(1-\nu)}{\OPT}\right)w_{t}(H_t).
	\end{align}
	Consider an optimal solution $P^*\subseteq H$. Then (as $P^*$ sees all points in $H\supseteq H_t$), 
	\begin{align}\label{e1-1-1-1}
	w_t(H_t)&=w_t\left(\bigcup_{q\in P^*}\Vis_{H_t}(q)\right)\le \sum_{q\in P^*}w_t(\Vis_{H_t}(q)).
	\end{align}
	From \raf{e1-1-1-1} it follows that there is a point $q\in P^*$ such that  $w_t(\Vis_{H_t}(q))\ge\frac{w_t(H_t)}{\OPT},$ 
	and thus by the choice of $p_{t+1}$, $w_t(\Vis_{H_t}(p_{t+1}))\ge(1-\nu)w_t(\Vis_{H_t}(q))\ge\frac{(1-\nu)w_t(H_t)}{\OPT}$. Consequently, as $H_{t+1}\subseteq H_t$, we get
	\begin{align*}
	w_{t+1}(H_{t+1})&\le w_{t+1}(H_{t})=w_t(H_t)-\eps \cdot w_t(\Vis_{H_t}(p_{t+1}))\\
	&\le w_t(H_t)-\eps\cdot\frac{(1-\nu)w_t(H_t)}{\OPT}=\left(1-\frac{\eps(1-\nu)}{\OPT}\right)w_t(H_t)\\&<\exp\left(-\frac{\eps(1-\nu)}{\OPT}\right)w_t(H_t).
	\end{align*}
	This gives~\raf{e1-1}, repeated applications of which yields the claim.
\end{proof} 

Define $t_{\max}:=\frac{\OPT}{\eps(1-\nu)}\left(T\ln\frac{1}{1-\eps}+\ln\frac{1}{\delta}\right)$.

\begin{lemma}\label{l-bd1} After at most $t_{\max}$ iterations, we have $w_0(H_{t_{\max}})<\delta\cdot w_0(H)$.
\end{lemma}
\begin{proof}
	Lemma~\ref{l1} implies that, for $t:=t_{\max}$, we have
	\begin{align*}
	w_t(H_t)<e^{-\frac{\eps(1-\nu)t}{\OPT}}w_{0}(H).
	\end{align*}
	By Observation~\ref{ob1}, $w_t(H_t)>(1-\eps)^Tw_0(H_t)$. Thus, if $w_0(H_t)\ge\delta\cdot w_0(H)$, we get
	\begin{align*}
	(1-\eps)^T\delta<e^{-\frac{\eps(1-\nu)t}{\OPT}},
	\end{align*}
	giving $t<\frac{\OPT}{\eps(1-\nu)}\left(T\ln\frac{1}{1-\eps}+\ln\frac{1}{\delta}\right)=t_{\max}$, in contradiction to $t=t_{\max}$.
\end{proof}


\begin{lemma}\label{l-bd2} Using $T=\frac1{\eps^2}\ln\frac{1}{\delta}$ and $\eps \leq 0.68$, the while-loop in Algorithm~\ref{alg} terminates in at most $t_{\max}$ iterations with a $(\frac{1+2\eps}{1-\nu},1-\delta)$-approximate fractional solution $(\widehat P,\widehat\mu)$ for $H$.
\end{lemma}
\begin{proof}
	By Lemma~\ref{l-bd1},  the while-loop in Algorithm \ref{alg} terminates in iteration $t_f \le t_{\max}$.
	We define the fractional solution $(\widehat P,\widehat\mu)$ of support $\widehat P=P_{t_f}$ and with $\widehat\mu(p)=\frac1T$ for $p\in \widehat P$.
	\medskip

	\noindent{\it $(1-\delta)$-Feasibility:} By the stopping criterion, $w_0(H_{t_f})<\delta\cdot w_0(H)$. Moreover, for any $q\in H\setminus H_{t_f}$, we have
	$\widehat\mu(\Vis(q))=\sum_{p\in \widehat P\cap \Vis(q)}\widehat\mu(p)=\frac{1}{T}|\widehat P\cap \Vis(q)|\ge 1$, since $|\widehat P\cap \Vis(q)|\ge T$, for all $q\in H\setminus H_t$.

	\medskip

	\noindent{\it Quality of the fractional guarding set $\widehat \mu$:}
	Using $T=\frac1{\eps^2}\ln\frac{1}{\delta}$, we have
	\begin{align*}
	\frac{\widehat\mu(\widehat P)}{\OPT}&=\frac{|\widehat P|}{T\cdot \OPT}=\frac{t_f}{T\cdot z^*_\cF}\le\frac{t_{\max}}{T\cdot \OPT}=\frac{1}{\eps(1-\nu)}\left(\ln\frac{1}{1-\eps}+\frac1T\ln\frac{1}{\delta}\right)\\
	&\le\frac{1}{1-\nu}\left(\frac{1}{\eps}\cdot\ln\frac{1}{1-\eps}+\eps\right)<\frac{1+2\eps}{1-\nu},	
	\end{align*}
	for $\eps \leq 0.68$. 
\end{proof}


    Note that the running time is {\it output-sensitive} as it depends on the value of $\OPT\le n$. 


    \medskip

\noindent{\it Proof of Theorem~\ref{t1}.}
Given the $(\frac{1+2\eps}{1-\nu},1-\delta)$-approximate fractional solution $(\widehat P,\widehat\mu)$ for $H$, obtained at the end of the while-loop in Algorithm~\ref{alg} (as guaranteed by Lemma~\ref{l-bd2}), we use a similar argument as in \cite{ERS05} for rounding the fractional solution. Let $\epsilon:=\frac1{\widehat\mu(\widehat P)}$. By definition of $\widehat \mu$, we have $\widehat\mu(\widehat P)\le\frac{1+2\eps}{1-\nu}\cdot\OPT$, and $\widehat\mu(\Vis(q))\ge 1=\epsilon\cdot\widehat\mu(\widehat P)$ for all $q\in H'$, where $H'\subseteq H$ has $\area(H')\ge(1-\delta)\area(H)$. If $\epsilon=1$ than $1=\widehat\mu(\widehat P)\ge\widehat \mu(\Vis(q))\ge 1$, for all $q\in H'$, implies that $\widehat P\subseteq\Vis(q)$ for all $q\in H'$, and thus taking any point in $\widehat P$ gives a solution satisfying the claim in the theorem. Thus we may assume that $\epsilon<1$.
Consider the range space $\cF_{H'}=(H,\{\Vis(q)~:~q\in H'\})$ defined by the visibility polygons of points in $H'$ (w.r.t. $H$), together with the weight function $\widehat\mu:\widehat P\to\RR_+$. According to the results stated in Section~\ref{sec:VCd}, $\VCd(\cF_{H'})\le\VCd(\cF_H)=O(\log (h+2))$ and an $\epsilon$-net $P\subseteq \widehat P$ of size 
\begin{align*}
|P|&=s_{\cF_H}\left(\frac{1}{\epsilon}\right)=O(\widehat\mu(\widehat P)\cdot\log(h+2)\cdot\log(\widehat\mu(\widehat P)\cdot\log( h+2)))\\&=O\left(\frac{1+2\eps}{1-\nu}\cdot\log(h+2)\cdot\log\Big(\frac{1+2\eps}{1-\nu}\cdot\OPT\cdot\log(h+2)\Big)\right)\cdot\OPT
\end{align*} 
can be computed deterministically in time $\poly(n,h^{\log\log (h\cdot|\widehat P|)},|\widehat P|)$.  The definition of $P$ implies that $P\cap \Vis(q)\neq\emptyset$ for all $q\in H'$. The theorem follows.  
\qed

\label{sec:det}

In this section, we show how the oracle \MO$(H,H',w',\nu)$ can be implemented in polynomial time, for a given a polygon $H$  and an accuracy parameter $\nu\in[0,1)$, when $H'=H_t\subseteq H$ is the active polygon in iteration $t$ of Algorithm~\ref{alg}, and  $w'=w_t:H\to\RR_+$ is the weight function in iteration $t$.
We assume that the components of the vertices of $H$ have rational representation, with maximum bit-length $L$ for each component.

\label{rand-samp}

Given $\epsilon,\gamma\in(0,1)$, a polygon $H$ and a subset $H'\subseteq H$, a set $Q\subseteq H$ is said to be a (one-sided) {\it relative} $(\epsilon,\gamma)$-approximation\footnote{According to the standard definition of relative $(\epsilon,\gamma)$-approximation (\cite{AS08,C00,CM22,HS11,LLS01,VC71}), we would require
	\begin{equation}\label{rel-eps-approx-0}
	\frac{|Q\cap \Vis(q)|}{ |Q|}\le\frac{\area(\Vis(q))}{\area(H)}+\gamma\cdot\max\left\{\frac{\area(\Vis(q))}{\area(H)},\epsilon\right\}
	\end{equation}
	to hold for all $q\in H$. It is known~\cite{LLS01} (in fact, for any range space of constant VC-dimension) that a uniform random sample $Q$ from $H$ of size $r:=O\left(\frac{1}{\epsilon\gamma^2}\log\big(\frac1{\epsilon\sigma}\big)\right)$ is a relative $(\epsilon,\gamma)$-approximation with probability at least $1-\sigma$. However, it is not clear if this stronger definition can lead to a better bound on the running time of the sampling approach (as a function of $\frac1\delta$).
} (see, e.g., \cite{CM22,HS11,LLS01}) for $H'$ if 
\begin{equation}\label{rel-eps-approx}
\frac{|Q\cap H'|}{ |Q|}\le\frac{\area(H')}{\area(H)}+\gamma\cdot\max\left\{\frac{\area(H')}{\area(H)},\epsilon\right\}.
\end{equation}

By the standard Chernoff bound, a uniform random sample $Q$ from $H$ of size $r$ fails to satisfy~\raf{rel-eps-approx} with probability at most $\rho:=e^{-\frac{\epsilon \gamma^2r}{3}}$ (see, e.g., \cite{CM22}).


To get an approximate guarding set for $H$, it would be enough to obtain a random sample $Q\subseteq H$ of size $r:=O(\frac{\OPT\cdot\log\OPT}{\delta^2}\log\frac{\OPT}{\sigma})$ (where $\OPT$ can be guessed within a factor of $2$ using exponential search), and then solve a discrete hitting set problem on $H$, where the requirement is to only guard all points in $Q$ (e.g., using the Br\"{o}nnimann-Goodrich approach \cite{BG95} as the set of candidate guard locations can now be descritized). Let $P$ be the approximate guarding set obtained of size at $k:=O(\OPT\cdot\log \OPT)$. Using~\raf{rel-eps-approx}, it can be easily seen that, with high probability, $P$ guards at least $(1-\delta)$-fraction of the area of $H$. Indeed, let $P=\{p_1,\ldots,p_k\}$, and for $t\in\{1,\ldots,k\}$, let $H_t$ be the part of $H$ that is not seen by any of the points in $\{p_1,\ldots,p_{t}\}.$ 
Let $E_t$ be the event that 
$$\frac{|Q \cap \Vis_{H_t}(p_{t+1})|}{|Q|}\le (1+\gamma)\frac{\area(\Vis_{H_t}(p_{t+1}))}{\area(H)}+\gamma\epsilon.$$
By~\raf{rel-eps-approx},
\begin{align}\label{e1}
\Pr[E_t]&=\sum_{p\in H,H'\subseteq H}Pr[E_t~|~p_{t+1}=p,~\Vis_{H_t}(p_{t+1})=H']\cdot\Pr[p_{t+1}=p,~H'=H]\\
&\ge(1-\rho)\sum_{p\in H,H'\subseteq H}\Pr[p_{t+1}=p,~\Vis_{H_t}(p_{t+1})=H']=1-\rho.
\end{align}
Applying the union bound over $t\in\{0,1,\ldots,k-1\}$ in~\raf{e1}, we get with probability at least $1-k\rho$ that
\begin{align}\label{e2}
1\le\frac{|\{q\in Q:~\Vis(q)\cap P\ne\emptyset\}|}{|Q|}&=\sum_{t=0}^{k-1}\frac{|Q \cap \Vis_{H_t}(p_{t+1})|}{|Q|}\le (1+\gamma)\sum_{t=0}^{k-1}\frac{\area( \Vis_{H_t}(p_{t+1}))}{\area(H)}+\gamma\epsilon k\nonumber\\
&=(1+\gamma)\frac{\area(H)-\area(H_k)}{\area(H)}+\gamma\epsilon k,
\end{align}
where the first inequality in~\raf{e2} follows from the fact that $P$ is a guarding set for the points in $Q$ (with probability $1$). It follows from~\raf{e2} that $\area(H_k)\le\frac{\gamma}{1+\gamma}(1+\epsilon k)\area(H)$ holds with probability at least $1-k\rho$.  Setting $\epsilon:=\frac1k$, $\gamma:=\frac\delta2$ and $r:=\frac{12 k \ln \frac{k}{\sigma}}{\delta^2}$ (for a desired bound on the failure probability, $\sigma>0$), we get that $\area(H_k)\le\delta\cdot \area(H)$ holds with probability at least $1-\sigma$. Thus, we get (with high probability) an $(O(\log\OPT),1-\delta)$-approximation in time proportional to $\frac1{\delta^2}$.

By the $\epsilon$-net theorem~\cite{HW87,KPW92} , a random sample $Q$ from $H$ of size $O(\frac{d}{\epsilon}\log\frac{1}{\epsilon})$ is an $\epsilon$-net with probability $\Omega(1)$, where $d$ is the VC-dimension of the range space defined by the visibility polygons w.r.t $H$.  Let $H':=H\setminus \bigcup_{q\in Q}\Vis(q)$ be the part of $H$ not seen by any point in $Q$. Note that $H'=\{p\in H~:~q\not\in\Vis(p)\text{ for all }q\in Q\}=$. Thus, if $\area(H')\geq\delta\area(H)$, then there must exist a point $p\in H'$ such that $\area(\Vis(p))\ge\delta\area(H)$ which contradicts the fact that $Q$ is an $\epsilon$-net.  
\fi

\label{sec:BG}

The original Br\"{o}nnimann-Goodrich algorithm~\cite{BG95}  works for range spaces $(Q,\cR)$ with finite point set $Q$. If one wants to apply this algorithm to the art gallery problem, there are two possible directions:  

\begin{itemize}
	\item Discrtization using a grid $\Gamma$, where the candidate set of guards are restricted to lie on $\Gamma$. The difficulty of this approach is that the size of an optimum set of guards {\it restricted} to $\Gamma$ might be much larger than the size of an optimum set without any restriction. This was the approach used in~\cite{BM16} to give a randomized $O(\log \OPT)$-apporximation algorithm under the general position assumption stated in the introduction.

	\item Extension of the Br\"{o}nnimann-Goodrich algorithm for continuous range spaces. It can be shown (see~\cite{E16}) that the algorithm can be extended to work for the  (full coverage version of) the art gallery problem, but the running time may depend on the area of the smallest cell $R$ of the arrangement created in the course of the algorithm. More precisely, the number of iterations is $O(\OPT\cdot\log\frac{\area(Q)}{\area(R)})$. Since $R$ can be arbitrarily small, there is no guarantee that such an extension will terminate in polynomial (ore even finite) time.    
\end{itemize}
