For $\cR':=\{R_1,\ldots,R_t\}\subseteq\cR$, let $\cells(\cR):=\{\bigcap_{t'\in S}R_{t'}\setminus\bigcap_{t'\in [t]\setminus S}R_{t'}:~S\subseteq [t]\}\setminus\{\emptyset\}$ be the partition of $Q$ induced by $\cR'$. Define 
\begin{align}\label{delta0}
\delta_0:=\min_{\text{ finite } \cR'\subseteq\cR}\min_{P\in\cells(\cR')}\frac{\mu_0(P)}{\mu_0(Q)}.
\end{align}
\begin{theorem}\label{BG}
	Let $\cF=(Q,\cR)$ be a range space satisfying (A1) and (A3$'$) and admitting an $\epsilon$-net of size $s_{\cF}(\frac{1}{\epsilon})$, and $\mu:Q\to\RR_+$ be a measure feasible for \raf{FH}.
	For $\epsilon\le\frac{1}{2\mu(Q)}$, Algorithm~\ref{BG-alg} finds a hitting set  of size $s_{\cF}(\frac{1}{\epsilon})$ in $O(\mu(Q)\log\frac{1}{\delta_0})$ iterations.	
\end{theorem}
\begin{proof} Let $\cR_t=\{R_1,\ldots,R_t\}\subseteq \cR$ be the set of ranges whose weights are doubled in iterations $1,\ldots,t$. For $P\subseteq Q$, define $\deg_t(P):=|\{R\in\cR_t:~R\supseteq P\}|$.
	For two measures $\mu',\mu'':Q\to\RR_+$, denote by $\langle \mu',\mu''\rangle$ the inner product: 
	$\langle \mu',\mu''\rangle:=\int_{q\in Q}\mu'(q)\mu''(q)dq$.
	Then 
	\begin{equation}\label{e1-1}
	\langle \mu_t,\mu\rangle=\sum_{P\in\cells(\cR_t)}2^{\deg_t(P)}\mu(P).
	\end{equation}
	By the feasibility of $\mu$, for every $R_{t'} \in \cR_{t}$, we have that $\mu(R_{t'})=\int_{q\in Q}\mu(q)\bone_{q\in R_{t'}}dq \geq 1$. Thus,
	\begin{align}\label{e2-2}
	t&\le \sum_{t'=1}^t\mu(R_{t'})=\sum_{t'=1}^t\int_{q\in Q} \mu(q)\bone_{q\in R_{t'}}dq\nonumber\\
	& = \int_{q \in Q} \sum_{t'=1}^t\mu(q)\bone_{q\in R_{t'}}dq=\int_{q \in Q} \mu(q) \deg_t(q)dq\nonumber\\
	&=\sum_{P\in\cells(\cR_t)}\deg_t(P)\mu(P). 
	\end{align}
	From \raf{e1-1} and \raf{e2-2}, we obtain
	\begin{align}\label{e3-3}
	\frac{\langle \mu_t,\mu\rangle}{\mu(Q)}&=\sum_{P\in\cells(\cR_t)}2^{\deg_t(P)}\frac{\mu(P)}{\mu(Q)}
	\ge 2^{\sum_{P\in\cells(\cR_t)}\deg_t(P)\frac{\mu(P)}{\mu(Q)}}\ge 2^{t/\mu(Q)},
	\end{align}
	where the first inequality follows by the convexity of the exponential function while the second follows from \raf{e2-2}. 
	Since the range $R_{t+1}$ chosen in step~\ref{BG-s2} does not intersect the $\epsilon$-net $P$ chosen in step~\ref{BG-s1}, we have $\mu_t(R_{t+1})<\epsilon \mu_t(Q)$ and thus $\mu_{t+1}(Q)=\mu_t(Q)+\mu_t(R_{t+1})<(1+\epsilon)\mu_t(Q).$ 
	It follows that 
	\begin{align}\label{e4-4} 
	(1+\epsilon)^t>\frac{\mu_t(Q)}{\mu_0(Q)}&=\sum_{P\in\cells(\cR_t)}2^{\deg_t(P)}\frac{\mu_0(P)}{\mu_0(Q)}.
	\end{align}
	From \raf{e3-3}, we get that there is a $P\in\cells(\cR_t)$ such that $2^{\deg_t(P)}\ge 2^{t/\mu(Q)}$. On the other hand, \raf{e4-4} implies that $2^{\deg_t(P)}\frac{\mu_0(P)}{\mu_0(Q)}<(1+\epsilon)^t<e^{\epsilon t}$. Putting the two inequalities together, we obtain
	\begin{align}\label{e5-5}
	\frac{t\ln 2}{\mu(Q)}\le \epsilon t+\ln\frac{\mu_0(Q)}{\mu_0(P)}.
	\end{align}
	Since $\epsilon\le\frac{1}{2\mu(Q)}$, we get from \raf{e5-5} that $t\le \frac{1}{\ln 2-0.5}\cdot\mu(Q)\ln\frac{\mu_0(Q)}{\mu_0(P)}.$
\end{proof}
Let $\mu^*$ be a $(1+\eps)$-approximate solution for \raf{FH}. 
We can use Algorithm~\ref{BG-alg} in a binary search manner to determine whether or not $\mu^*(Q)\le(1+\rho)^i$, for any $\rho>0$ and $i\in\ZZ_+$, by checking if the algorithm stops with a hitting set in $\frac{1}{\ln 2-0.5}\cdot(1+\rho)^i\log\frac{1}{\delta_0}$ iterations. 
As $1\le \mu^*(Q)\le n$ if we assume (A2), we need only $O(\log_{1+\rho} n)$ binary search steps. 

We mention an application of Theorem~\ref{BG} when $Q$ is finite. Let $\mu_0\equiv 1$. Then $\delta_0\ge \frac{1}{|Q|}$, and Theorem~\ref{BG} implies that a hitting set of size $s_{\cF}(O(\mu^*(Q)))$ can be found in $O(\mu^*(Q)\log n\log |Q|)$ iterations.

\begin{remark}\label{r1}
	One can also extend the second algorithm and analysis suggested in \cite{AP14} to the infinite case, to get as randomized algorithm that computes, with probability at least $\frac{1}{7}$ a hitting set of size $s_{\cF}(8z_{\cF}^*)$ in $O(z_{\cF}^*\ln(\frac{1}{\delta_0(\delta_0')^2}))$, where $\delta_0$ is as defined in \raf{delta0}, and 
	\begin{align}\label{delta0'}
	\delta_0':=\min_{\text{ finite } P\subseteq Q}\frac{w_0(\cR[P])}{w_0(\cR)},
	\end{align}
	where $\cR[P]:=\{R\in\cR:~R\cap Q= P\}$.
\end{remark}
\fi

